INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'pearl-bay-hotel-case-1', 'Manama Dialogue Official Delegation Wing', 'استضافة الوفود الرسمية لمنتدى حوار المنامة', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Muharraq with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Muharraq وفق أعلى معايير الجودة والالتزام.', 230, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://pearlbayhotel.bh/work/pearl-bay-hotel-case-1', 'Muharraq, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'pearl-bay-hotel-2026-outlook', 'Pearl Bay Hotel 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — فندق خليج اللؤلؤة', 'Key operational benchmarks, real metrics, and 2026 guidance from Pearl Bay Hotel in Muharraq.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من فندق خليج اللؤلؤة في Muharraq.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues. Focusing on Sea-View Executive Suite (Night), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية. من خلال خدمة جناح تنفيذي مطل على البحر (ليلة) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues.</p><p>Focusing on <strong>Sea-View Executive Suite (Night)</strong>, our Muharraq specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية.</p><p>من خلال خدمة <strong>جناح تنفيذي مطل على البحر (ليلة)</strong>، يعمل فريقنا في Muharraq على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Pearl Bay Hotel 2026 GCC Market Outlook & Benchmarks | Pearl Bay Hotel', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — فندق خليج اللؤلؤة | فندق خليج اللؤلؤة', 'Executive guide by Pearl Bay Hotel covering Sea-View Executive Suite (Night) benchmarks in Bahrain.', 'دليل تنفيذي من فندق خليج اللؤلؤة حول معايير جناح تنفيذي مطل على البحر (ليلة) في البحرين.', 'Insights', '{"hotel","insights","Muharraq","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Pearl Bay Hotel initiate a Sea-View Executive Suite (Night) engagement?', 'كم يستغرق بدء تنفيذ خدمة جناح تنفيذي مطل على البحر (ليلة) لدى فندق خليج اللؤلؤة؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Muharraq.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Muharraq.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'pearl-bay-hotel-case-2', 'Michelin Guest-Chef Residency Week', 'أسبوع استضافة الطهاة العالميين الحائزين على ميشلان', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Muharraq with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Muharraq وفق أعلى معايير الجودة والالتزام.', 870, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://pearlbayhotel.bh/work/pearl-bay-hotel-case-2', 'Muharraq, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'pearl-bay-hotel-service-standards', 'Inside Our Rooms SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في جناح تنفيذي مطل على البحر (ليلة)', 'Key operational benchmarks, real metrics, and 2026 guidance from Pearl Bay Hotel in Muharraq.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من فندق خليج اللؤلؤة في Muharraq.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues. Focusing on Boardroom Full-Day Package, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية. من خلال خدمة باقة قاعة الاجتماعات ليوم كامل نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>64-key waterfront boutique hotel blending traditional Muharraq architecture with modern executive hospitality and meeting venues.</p><p>Focusing on <strong>Boardroom Full-Day Package</strong>, our Muharraq specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>فندق بوتيكي يضم 64 جناحاً على واجهة المحرق يجمع بين العمارة التراثية والضيافة العصرية.</p><p>من خلال خدمة <strong>باقة قاعة الاجتماعات ليوم كامل</strong>، يعمل فريقنا في Muharraq على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Rooms SLA: Speed, Quality & Auditability | Pearl Bay Hotel', 'معايير اتفاقية مستوى الخدمة والجودة في جناح تنفيذي مطل على البحر (ليلة) | فندق خليج اللؤلؤة', 'Executive guide by Pearl Bay Hotel covering Boardroom Full-Day Package benchmarks in Bahrain.', 'دليل تنفيذي من فندق خليج اللؤلؤة حول معايير باقة قاعة الاجتماعات ليوم كامل في البحرين.', 'Operations', '{"hotel","operations","Muharraq","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-144510-1 and VAT ID 200014451000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-144510-1 والرقم الضريبي 200014451000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-3', 'pcat-cms-3', 'pearl-bay-hotel-case-3', '92% Peak-Season ADR Occupancy Record', 'تحقيق نسبة إشغال قياسية 92% في الموسم السياحي', 'Dilmun Energy Partners', 2025, 'Delivered for Dilmun Energy Partners across Muharraq with measurable SLA benchmarks.', 'تم التنفيذ لصالح شركاء دلمون للطاقة في Muharraq وفق أعلى معايير الجودة والالتزام.', 265, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://pearlbayhotel.bh/work/pearl-bay-hotel-case-3', 'Muharraq, Bahrain') ON CONFLICT (id) DO NOTHING;
